1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
14	
15	const BASE_PREMIUMS: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	};
21	
22	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
23	
24	const applyFirstInsuranceSurcharge = (amount: number): number =>
25	  (amount * (100 + FIRST_INSURANCE_SURCHARGE_PERCENT)) / 100;
26	
27	export const quote = (
28	  customer: Customer,
29	  items: Item[],
30	  contractIndex: number,
31	): number => {
32	  const base = items.reduce((sum, item) => sum + basePremium(item), 0);
33	  return applyFirstInsuranceSurcharge(base) + PROCESSING_FEE;
34	};
35	
36	export const claim = (): number => {
37	  return undefined as unknown as number;
38	};
