1	import { describe, it, expect } from "vitest";
2	import { quote, claim } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office — quote", () => {
5	  // Edge case: empty list
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    expect(quote({ yearsWithMHPCO: 0 }, [], 0)).toBe(5);
8	  });
9	
10	  // Base premiums for single main items (base + 10% first insurance + 5 fee)
11	  it("single sword → base premium 100 G (total 100 + 10 first + 5 fee = 115)", () => {
12	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }], 0)).toBe(115);
13	  });
14	  it("single amulet → base premium 60 G (total 60 + 6 first + 5 fee = 71)", () => {
15	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }], 0)).toBe(71);
16	  });
17	  it("single staff → base premium 80 G (total 80 + 8 first + 5 fee = 93)", () => {
18	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }], 0)).toBe(93);
19	  });
20	  it("single potion → base premium 40 G (total 40 + 4 first + 5 fee = 49)", () => {
21	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "potion" }], 0)).toBe(49);
22	  });
23	
24	  // Components
25	  it.todo("single rune → base premium 25 G");
26	  it.todo("single moonstone → base premium 25 G");
27	
28	  // Building block of 3 alike components
29	  it.todo("2 runes → 50 G base premium (no block)");
30	  it.todo("3 runes → 60 G base premium (block applies)");
31	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
32	  it.todo("7 runes → 175 G base premium");
33	
34	  // "Alike" components — same type only
35	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
36	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
37	
38	  // Premium modifiers — item-specific
39	  it.todo("cursed sword adds 50% risk surcharge (50 G on base 100 G)");
40	  it.todo("highly enchanted sword (enchantment ≥ 5) adds 30% surcharge");
41	  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
42	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
43	  it.todo("sword with enchantment 5 and cursed → both surcharges apply");
44	
45	  // Policy-wide modifiers
46	  it.todo("long-standing customer (≥ 2 years) receives 20% loyalty discount");
47	  it.todo("customer with exactly 2 years → loyalty discount applies");
48	  it.todo("first insurance carries 10% initial assessment surcharge");
49	  it.todo("15% discount on each contract after the first");
50	
51	  // Processing fee
52	  it.todo("a 5 G processing fee is added to every premium");
53	
54	  // Modifier scope on multi-item policies
55	  it.todo(
56	    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (of cursed item base) → 210 G before further modifiers and fee",
57	  );
58	
59	  // Rounding in MHPCO's favor
60	  it.todo("premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
61	
62	  // Integration examples
63	  it.todo(
64	    "newcomer with cursed sword (steel, ench 3), 0 years → premium 165 G",
65	  );
66	  it.todo(
67	    "long-standing customer 2nd contract: cursed sword (steel, ench 7), 3 years → premium 160 G",
68	  );
69	  it.todo(
70	    "first insurance surcharge applies per item regardless of customer history",
71	  );
72	
73	  // Insurance sum / cap (exposed via quote result or claim)
74	  it.todo("two swords → insurance sum 2000 G, cap 4000 G");
75	  it.todo("sword + amulet → insurance sum 1600 G, cap 3200 G");
76	  it.todo("sword + 3 runes (block) → insurance sum 1750 G (block affects premium only)");
77	
78	  // Error handling
79	  it.todo("unknown item type (e.g. broomstick) → throws / error");
80	});
